124:/** Fill a form field, or CLEAR it when the test gives no value. A refused submission leaves what
125: *  was typed in the form (nothing in the contract says otherwise), so a value left over from the
126: *  attempt before must never leak into this one: the test states every field it submits. A field
127: *  the screen does not have is skipped. */
128:async function setField(scope: Locator | Page, testid: string, value: string | undefined): Promise<void> {
129:  const loc = scope.getByTestId(testid);
130:  if (value !== undefined) {
131:    await loc.fill(value);
132:  } else if ((await loc.count()) > 0) {
133:    await loc.fill('');
134:  }
135:}
