137:/** The result count a button shows once its action is done (how many were added, made, opened).
138: *  `was` is what the cell showed before the click. The count is taken once it differs from `was`,
139: *  or once the cell was seen cleared and shown again (README: a result is cleared when its button
140: *  is pressed again). Two identical results in a row can look the same on screen for the whole
141: *  wait: then, with no error showing and a value in the cell, that value is taken rather than
142: *  failing a step the app did take. */
143:async function countAfter(page: Page, cell: Locator, error: Locator, what: string, was: string): Promise<string | null> {
144:  let cleared = false;
145:  const done = async () => {
146:    if ((await cell.count()) === 0) return false;
147:    const now = await shown(cell);
148:    if (now === '') { cleared = true; return false; }
149:    return now !== was || was === '' || cleared;
150:  };
151:  try {
152:    return (await until(page, done, error, what)) ? await shown(cell) : null;
153:  } catch (e) {
154:    if (await error.isVisible().catch(() => false)) return null;
155:    if ((await cell.count()) > 0 && (await shown(cell)) !== '') return shown(cell);
156:    throw e;
157:  }
158:}
