82:/** Poll until `done` holds (true) or `error` is visible (false); throw when neither happens.
83: *  Each check returns as soon as it can. An error already visible at the first look after the
84: *  click may be left over from the action before (the screen clears it when a new action is
85: *  submitted, see README): it counts as this action's refusal once it has gone away and been
86: *  shown again, once its text changes, or once ERROR_GRACE has passed with no result.
87: *  `already` says `done` held BEFORE the action (watching a person already watched, saving a
88: *  setting at its current value): then the result on screen proves nothing, and the action
89: *  counts as taken only once ERROR_GRACE has passed with no refusal shown. */
90:async function until(page: Page, done: () => Promise<boolean>, error: Locator, what: string,
91:                     already = false): Promise<boolean> {
92:  const deadline = Date.now() + WAIT;
93:  let stale: string | null | undefined;   // text of an error visible at the first look; null if none
94:  let seenGone = false;
95:  const grace = Date.now() + ERROR_GRACE;
96:  while (Date.now() < deadline) {
97:    if (!already && await done()) return true;
98:    const visible = await error.isVisible().catch(() => false);
99:    if (stale === undefined) stale = visible ? await shown(error) : null;
100:    if (visible) {
101:      if (stale === null || seenGone || (await shown(error)) !== stale || Date.now() >= grace) return false;
102:    } else {
103:      seenGone = true;
104:    }
105:    // the state held before the action: an error still showing at the grace outranks it
106:    if (already && Date.now() >= grace && await done()) return true;
107:    await page.waitForTimeout(50);
108:  }
109:  if (await done()) return true;
110:  if (await error.isVisible().catch(() => false)) return false;
111:  throw new Error(`${what}: neither a result nor an error appeared within ${WAIT}ms`);
112:}
