118:/** A counter the screen shows after a bulk action: the number in the cell once it is visible. */
119:async function counter(page: Page, cell: Locator, error: Locator, what: string): Promise<number | null> {
120:  const ok = await until(page, async () => (await cell.count()) > 0 && (await shown(cell)) !== '', error, what);
121:  return ok ? Number(await shown(cell)) : null;
122:}
